<?php
require __DIR__.'/includes/bootstrap.php';requireLogin();$id=queryId('event_id');$q=$pdo->prepare('SELECT * FROM events WHERE event_id=?');$q->execute([$id]);$event=$q->fetch();if(!$event||!canManageAttendees($pdo,$event))abortRequest(403,'You cannot view this attendee list.');
$q=$pdo->prepare('SELECT b.*,u.name,u.email FROM bookings b JOIN users u ON u.user_id=b.user_id WHERE b.event_id=? ORDER BY b.created_at');$q->execute([$id]);$attendees=$q->fetchAll();$q=$pdo->prepare('SELECT w.*,u.name FROM waiting_list w JOIN users u ON u.user_id=w.user_id WHERE w.event_id=? ORDER BY w.joined_at,w.entry_id');$q->execute([$id]);$waiting=$q->fetchAll();
$pageTitle='Guest list';require __DIR__.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">THE PEOPLE MAKE IT</p><h1>Guest list.</h1><p class="muted"><?=e($event['title'])?></p></div><a class="button" href="scan.php">Open QR scanner ↗</a></div><p class="notice"><?=checkinOpen($event)?'Check-in is open.':'Check-in is not currently open. The default window is 2 hours before to 12 hours after the start.'?></p>
<div class="stats-grid"><div class="stat"><strong><?=count($attendees)?></strong><span>Confirmed</span></div><div class="stat"><strong><?=array_sum(array_column($attendees,'checked_in'))?></strong><span>Checked in</span></div><div class="stat"><strong><?=count($waiting)?></strong><span>Waiting</span></div></div>
<div class="table-wrap"><table><thead><tr><th>Guest</th><th>Email</th><th>Status</th><th>Admission</th></tr></thead><tbody><?php foreach($attendees as $a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['email'])?></td><td><?=$a['checked_in']?'Checked in':'Confirmed'?></td><td><?php if(!$a['checked_in']&&checkinOpen($event)):?><form method="post" action="checkin.php" data-confirm="Confirm manual check-in for this guest?"><?=csrfField()?><input type="hidden" name="event_id" value="<?=$id?>"><input type="hidden" name="booking_id" value="<?=(int)$a['booking_id']?>"><button class="secondary small">Manual check-in</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$attendees):?><tr><td colspan="4">No bookings yet.</td></tr><?php endif;?></tbody></table></div><h2>Waiting list · first come, first served</h2><div class="table-wrap"><table><thead><tr><th>Position</th><th>Name</th><th>Joined</th></tr></thead><tbody><?php foreach($waiting as $i=>$w):?><tr><td><?=$i+1?></td><td><?=e($w['name'])?></td><td><?=e($w['joined_at'])?></td></tr><?php endforeach;?><?php if(!$waiting):?><tr><td colspan="3">Nobody is waiting.</td></tr><?php endif;?></tbody></table></div>
<?php require __DIR__.'/includes/footer.php';?>
